SELECT     REPORT_DATE                                               AS \"Report Date\",     PO_NUMBER                                                 AS \"PO Number\",     ORDER_TYPE                                                AS \"Order Type\",     PO_STATUS                                                 AS \"PO Status Code\",     CASE PO_STATUS         WHEN 'W' THEN 'Worksheet'         WHEN 'S' THEN 'Submitted'         WHEN 'A' THEN 'Approved'         WHEN 'C' THEN 'Closed'         ELSE PO_STATUS     END                                                       AS \"PO Status Description\",     WRITTEN_DATE                                              AS \"PO Written Date\",     NOT_BEFORE_DATE                                           AS \"Not Before Date\",     NOT_AFTER_DATE                                            AS \"Not After Date\",     CURRENCY_CODE                                             AS \"Currency Code\",     SUPPLIER_ID                                               AS \"Supplier ID\",     SUPPLIER_NAME                                             AS \"Supplier Name\",     SUPPLIER_STATUS                                           AS \"Supplier Status\",     ITEM_ID                                                   AS \"Item ID\",     ITEM_DESCRIPTION                                          AS \"Item Description\",     ITEM_NUMBER_TYPE                                          AS \"Item Number Type\",     ITEM_LEVEL                                                AS \"Item Level\",     TRAN_LEVEL                                                AS \"Transaction Level\",     ITEM_STATUS                                               AS \"Item Status\",     ORDERABLE_IND                                             AS \"Orderable Indicator\",     DEPT_NO                                                   AS \"Department Number\",     DEPT_NAME                                                 AS \"Department Name\",     CLASS_NO                                                  AS \"Class Number\",     CLASS_NAME                                                AS \"Class Name\",     SUBCLASS_NO                                               AS \"Subclass Number\",     SUBCLASS_NAME                                             AS \"Subclass Name\",     LOCATION_ID                                               AS \"Location ID\",     LOC_TYPE                                                  AS \"Location Type\",     CASE LOC_TYPE         WHEN 'S' THEN STORE_NAME         WHEN 'W' THEN WH_NAME         ELSE TO_CHAR(LOCATION_ID)     END                                                       AS \"Location Name\",     QTY_ORDERED                                               AS \"Quantity Ordered\",     QTY_RECEIVED                                              AS \"Quantity Received\",     QTY_ORDERED - QTY_RECEIVED                               AS \"Quantity Outstanding\",     UNIT_COST                                                 AS \"Unit Cost\",     ROUND(QTY_ORDERED * UNIT_COST, 2)                        AS \"Total Ordered Cost\",     ORIGIN_COUNTRY_ID                                         AS \"Origin Country ID\",     VPN                                                       AS \"Vendor Product Number\",     CASE         WHEN WRONG_LEVEL_FLAG   = 'Y'         THEN 'WRONG ITEM LEVEL - Ordered at Item Level; must order at Tran Level'         WHEN NOT_ORDERABLE_FLAG = 'Y'         THEN 'NOT ORDERABLE - ORDERABLE_IND is N on Item Master'         WHEN WRONG_STATUS_FLAG  = 'Y'         THEN 'WRONG ITEM STATUS - Item is not Active (' || ITEM_STATUS || ')'         WHEN WRONG_NUMBER_TYPE  = 'Y'         THEN 'WRONG ITEM NUMBER TYPE - ' || ITEM_NUMBER_TYPE || ' not valid for this order type'         ELSE 'REVIEW REQUIRED - Check item and order configuration'     END                                                       AS \"Issue Type\",     CASE         WHEN WRONG_LEVEL_FLAG   = 'Y'         THEN '1 - HIGH: Order will not process correctly'         WHEN NOT_ORDERABLE_FLAG = 'Y'         THEN '2 - HIGH: Item cannot be ordered'         WHEN WRONG_STATUS_FLAG  = 'Y'         THEN '3 - MEDIUM: Inactive or discontinued item on active PO'         ELSE '4 - LOW: Review required'     END                                                       AS SEVERITY,     CASE         WHEN WRONG_LEVEL_FLAG   = 'Y'         THEN 'Cancel PO line; re-raise order using Tran Level item (' || TO_CHAR(TRAN_LEVEL) || ')'         WHEN NOT_ORDERABLE_FLAG = 'Y'         THEN 'Set ORDERABLE_IND = Y on Item Master or cancel this PO line'         WHEN WRONG_STATUS_FLAG  = 'Y'         THEN 'Confirm item status; update to Active or cancel PO line'         ELSE 'Review item and order type configuration with Buying team'     END                                                       AS \"Recommended Action\",     TOTAL_ISSUE_FLAGS                                         AS \"Total Issue Flags\"  FROM (

