SELECT         TRUNC(SYSDATE)                                        AS REPORT_DATE,         oh.ORDER_NO                                           AS PO_NUMBER,         oh.ORDER_TYPE,         oh.STATUS                                             AS PO_STATUS,         oh.WRITTEN_DATE,         oh.NOT_BEFORE_DATE,         oh.NOT_AFTER_DATE,         oh.CURRENCY_CODE,         oh.SUPPLIER                                           AS SUPPLIER_ID,         sp.SUP_NAME                                           AS SUPPLIER_NAME,         sp.SUP_STATUS                                         AS SUPPLIER_STATUS,         ol.ITEM                                               AS ITEM_ID,         im.ITEM_DESC                                          AS ITEM_DESCRIPTION,         im.ITEM_NUMBER_TYPE,         im.ITEM_LEVEL,         im.TRAN_LEVEL,         im.STATUS                                             AS ITEM_STATUS,         im.ORDERABLE_IND,         im.DEPT                                               AS DEPT_NO,         d.DEPT_NAME,         im.CLASS                                              AS CLASS_NO,         c.CLASS_NAME,         im.SUBCLASS                                           AS SUBCLASS_NO,         sc.SUB_NAME                                           AS SUBCLASS_NAME,         ol.LOCATION                                           AS LOCATION_ID,         ol.LOC_TYPE,         st.STORE_NAME,         wh.WH_NAME,         NVL(ol.QTY_ORDERED,  0)                               AS QTY_ORDERED,         NVL(ol.QTY_RECEIVED, 0)                               AS QTY_RECEIVED,         ol.UNIT_COST,         os.ORIGIN_COUNTRY_ID,         os.REF_ITEM                                           AS VPN,         CASE WHEN im.ITEM_LEVEL != im.TRAN_LEVEL              THEN 'Y' ELSE 'N'         END                                                   AS WRONG_LEVEL_FLAG,         CASE WHEN NVL(im.ORDERABLE_IND, 'Y') = 'N'              THEN 'Y' ELSE 'N'         END                                                   AS NOT_ORDERABLE_FLAG,         CASE WHEN im.STATUS != 'A'              THEN 'Y' ELSE 'N'         END                                                   AS WRONG_STATUS_FLAG,         CASE WHEN oh.ORDER_TYPE IN ('B','CO','RV')                   AND im.ITEM_NUMBER_TYPE NOT IN ('ITEM','REFITEM')              THEN 'Y' ELSE 'N'         END                                                   AS WRONG_NUMBER_TYPE,         (CASE WHEN im.ITEM_LEVEL != im.TRAN_LEVEL          THEN 1 ELSE 0 END          + CASE WHEN NVL(im.ORDERABLE_IND,'Y') = 'N'       THEN 1 ELSE 0 END          + CASE WHEN im.STATUS != 'A'                      THEN 1 ELSE 0 END         )                                                     AS TOTAL_ISSUE_FLAGS      FROM  MFCS_RDS.RDS_WV_ORDHEAD                   oh     JOIN  MFCS_RDS.RDS_WV_ORDLOC                    ol   ON  oh.ORDER_NO = ol.ORDER_NO     JOIN  MFCS_RDS.RDS_WV_ORDSKU                    os   ON  ol.ORDER_NO = os.ORDER_NO                                                         AND  ol.ITEM     = os.ITEM     JOIN  MFCS_RDS.RDS_WV_ITEM_MASTER               im   ON  ol.ITEM     = im.ITEM     JOIN  MFCS_RDS.RDS_WV_DEPS                      d    ON  im.DEPT     = d.DEPT     JOIN  MFCS_RDS.RDS_WV_CLASS                     c    ON  im.DEPT     = c.DEPT                                                         AND  im.CLASS    = c.CLASS     JOIN  MFCS_RDS.RDS_WV_SUBCLASS                  sc   ON  im.DEPT     = sc.DEPT                                                         AND  im.CLASS    = sc.CLASS                                                         AND  im.SUBCLASS = sc.SUBCLASS     LEFT JOIN MFCS_RDS.RDS_WV_SUPS                  sp   ON  oh.SUPPLIER  = sp.SUPPLIER     LEFT JOIN MFCS_RDS.RDS_WV_STORE                 st   ON  ol.LOCATION  = st.STORE     LEFT JOIN MFCS_RDS.RDS_WV_WH                    wh   ON  ol.LOCATION  = wh.WH     WHERE         oh.STATUS IN ('W','S','A')         AND oh.WRITTEN_DATE &gt;= ADD_MONTHS(SYSDATE, -3)  )  