ntry ID\",\"isUserCalculation\":false},{\"prepColumnName\":\"Vendor Product Number\",\"isUserCalculation\":false},{\"prepColumnName\":\"Issue Type\",\"isUserCalculation\":false},{\"prepColumnName\":\"SEVERITY\",\"isUserCalculation\":false},{\"prepColumnName\":\"Recommended Action\",\"isUserCalculation\":false},{\"prepColumnName\":\"Total Issue Flags\",\"isUserCalculation\":false}],\"transforms\":[{\"id\":\"1\",\"type\":\"PROPERTY_CHANGE\",\"sourceColumns\":[\"PO Number\"],\"expressionSourceColumns\":[\"PO Number\"],\"outputColumns\":[],\"options\":{\"outputColumnAggrRule\":\"none\",\"outputColumnDisplayName\":\"PO Number\",\"outputColumnRole\":\"Attribute\",\"afterColumn\":\"PO Number\"},\"applied\":true,\"inplace\":true,\"rename\":false,\"allowEdit\":false,\"generatesOutputColumns\":false,\"unsavedTransform\":false,\"parentId\":null},{\"id\":\"2\",\"type\":\"PROPERTY_CHANGE\",\"sourceColumns\":[\"Supplier ID\"],\"expressionSourceColumns\":[\"Supplier ID\"],\"outputColumns\":[],\"options\":{\"outputColumnAggrRule\":\"none\",\"outputColumnDisplayName\":\"Supplier ID\",\"outputColumnRole\":\"Attribute\",\"afterColumn\":\"Supplier ID\"},\"applied\":true,\"inplace\":true,\"rename\":false,\"allowEdit\":false,\"generatesOutputColumns\":false,\"unsavedTransform\":false,\"parentId\":\"1\"},{\"id\":\"3\",\"type\":\"PROPERTY_CHANGE\",\"sourceColumns\":[\"Item Level\"],\"expressionSourceColumns\":[\"Item Level\"],\"outputColumns\":[],\"options\":{\"outputColumnAggrRule\":\"none\",\"outputColumnDisplayName\":\"Item Level\",\"outputColumnRole\":\"Attribute\",\"afterColumn\":\"Item Level\"},\"applied\":true,\"inplace\":true,\"rename\":false,\"allowEdit\":false,\"generatesOutputColumns\":false,\"unsavedTransform\":false,\"parentId\":\"2\"},{\"id\":\"4\",\"type\":\"PROPERTY_CHANGE\",\"sourceColumns\":[\"Transaction Level\"],\"expressionSourceColumns\":[\"Transaction Level\"],\"outputColumns\":[],\"options\":{\"outputColumnAggrRule\":\"none\",\"outputColumnDisplayName\":\"Transaction Level\",\"outputColumnRole\":\"Attribute\",\"afterColumn\":\"Transaction Level\"},\"applied\":true,\"inplace\":true,\"rename\":false,\"allowEdit\":false,\"generatesOutputColumns\":false,\"unsavedTransform\":false,\"parentId\":\"3\"},{\"id\":\"5\",\"type\":\"PROPERTY_CHANGE\",\"sourceColumns\":[\"Department Number\"],\"expressionSourceColumns\":[\"Department Number\"],\"outputColumns\":[],\"options\":{\"outputColumnAggrRule\":\"none\",\"outputColumnDisplayName\":\"Department Number\",\"outputColumnRole\":\"Attribute\",\"afterColumn\":\"Department Number\"},\"applied\":true,\"inplace\":true,\"rename\":false,\"allowEdit\":false,\"generatesOutputColumns\":false,\"unsavedTransform\":false,\"parentId\":\"4\"},{\"id\":\"6\",\"type\":\"PROPERTY_CHANGE\",\"sourceColumns\":[\"Class Number\"],\"expressionSourceColumns\":[\"Class Number\"],\"outputColumns\":[],\"options\":{\"outputColumnAggrRule\":\"none\",\"outputColumnDisplayName\":\"Class Number\",\"outputColumnRole\":\"Attribute\",\"afterColumn\":\"Class Number\"},\"applied\":true,\"inplace\":true,\"rename\":false,\"allowEdit\":false,\"generatesOutputColumns\":false,\"unsavedTransform\":false,\"parentId\":\"5\"},{\"id\":\"7\",\"type\":\"PROPERTY_CHANGE\",\"sourceColumns\":[\"Subclass Number\"],\"expressionSourceColumns\":[\"Subclass Number\"],\"outputColumns\":[],\"options\":{\"outputColumnAggrRule\":\"none\",\"outputColumnDisplayName\":\"Subclass Number\",\"outputColumnRole\":\"Attribute\",\"afterColumn\":\"Subclass Number\"},\"applied\":true,\"inplace\":true,\"rename\":false,\"allowEdit\":false,\"generatesOutputColumns\":false,\"unsavedTransform\":false,\"parentId\":\"6\"},{\"id\":\"8\",\"type\":\"PROPERTY_CHANGE\",\"sourceColumns\":[\"Location ID\"],\"expressionSourceColumns\":[\"Location ID\"],\"outputColumns\":[],\"options\":{\"outputColumnAggrRule\":\"none\",\"outputColumnDisplayName\":\"Location ID\",\"outputColumnRole\":\"Attribute\",\"afterColumn\":\"Location ID\"},\"applied\":true,\"inplace\":true,\"rename\":false,\"allowEdit\":false,\"generatesOutputColumns\":false,\"unsavedTransform\":false,\"parentId\":\"7\"}],\"recommendations\":[],\"dataSubsetInfos\":{\"queryEditMode\":1,\"filterbarSettings\":{},\"uiSqlStatement\":\"

-- ── Query 3 ────────────────────────────────────────────────────────────
SELECT\\n        TRUNC(SYSDATE)                                        AS REPORT_DATE,\\n        oh.ORDER_NO                                           AS PO_NUMBER,\\n        oh.ORDER_TYPE,\\n        oh.STATUS                                             AS PO_STATUS,\\n        oh.WRITTEN_DATE,\\n        oh.NOT_BEFORE_DATE,\\n        oh.NOT_AFTER_DATE,\\n        oh.CURRENCY_CODE,\\n        oh.SUPPLIER                                           AS SUPPLIER_ID,\\n        sp.SUP_NAME                                           AS SUPPLIER_NAME,\\n        sp.SUP_STATUS                                         AS SUPPLIER_STATUS,\\n        ol.ITEM                                               AS ITEM_ID,\\n        im.ITEM_DESC                                          AS ITEM_DESCRIPTION,\\n        im.ITEM_NUMBER_TYPE,\\n        im.ITEM_LEVEL,\\n        im.TRAN_LEVEL,\\n        im.STATUS                                             AS ITEM_STATUS,\\n        im.ORDERABLE_IND,\\n        im.DEPT                                               AS DEPT_NO,\\n        d.DEPT_NAME,\\n        im.CLASS                                              AS CLASS_NO,\\n        c.CLASS_NAME,\\n        im.SUBCLASS                                           AS SUBCLASS_NO,\\n        sc.SUB_NAME                                           AS SUBCLASS_NAME,\\n        ol.LOCATION                                           AS LOCATION_ID,\\n        ol.LOC_TYPE,\\n        st.STORE_NAME,\\n        wh.WH_NAME,\\n        NVL(ol.QTY_ORDERED,  0)                               AS QTY_ORDERED,\\n        NVL(ol.QTY_RECEIVED, 0)                               AS QTY_RECEIVED,\\n        ol.UNIT_COST,\\n        os.ORIGIN_COUNTRY_ID,\\n        os.REF_ITEM                                           AS VPN,\\n        CASE WHEN im.ITEM_LEVEL != im.TRAN_LEVEL\\n             THEN 'Y' ELSE 'N'\\n        END                                                   AS WRONG_LEVEL_FLAG,\\n        CASE WHEN NVL(im.ORDERABLE_IND, 'Y') = 'N'\\n             THEN 'Y' ELSE 'N'\\n        END                                                   AS NOT_ORDERABLE_FLAG,\\n        CASE WHEN im.STATUS != 'A'\\n             THEN 'Y' ELSE 'N'\\n        END                                                   AS WRONG_STATUS_FLAG,\\n        CASE WHEN oh.ORDER_TYPE IN ('B','CO','RV')\\n                  AND im.ITEM_NUMBER_TYPE NOT IN ('ITEM','REFITEM')\\n             THEN 'Y' ELSE 'N'\\n        END                                                   AS WRONG_NUMBER_TYPE,\\n        (CASE WHEN im.ITEM_LEVEL != im.TRAN_LEVEL          THEN 1 ELSE 0 END\\n         + CASE WHEN NVL(im.ORDERABLE_IND,'Y') = 'N'       THEN 1 ELSE 0 END\\n         + CASE WHEN im.STATUS != 'A'                      THEN 1 ELSE 0 END\\n        )                                                     AS TOTAL_ISSUE_FLAGS\\n\\n    FROM  MFCS_RDS.RDS_WV_ORDHEAD                   oh\\n    JOIN  MFCS_RDS.RDS_WV_ORDLOC                    ol   ON  oh.ORDER_NO = ol.ORDER_NO\\n    JOIN  MFCS_RDS.RDS_WV_ORDSKU                    os   ON  ol.ORDER_NO = os.ORDER_NO\\n                                                        AND  ol.ITEM     = os.ITEM\\n    JOIN  MFCS_RDS.RDS_WV_ITEM_MASTER               im   ON  ol.ITEM     = im.ITEM\\n    JOIN  MFCS_RDS.RDS_WV_DEPS                      d    ON  im.DEPT     = d.DEPT\\n    JOIN  MFCS_RDS.RDS_WV_CLASS                     c    ON  im.DEPT     = c.DEPT\\n                                                        AND  im.CLASS    = c.CLASS\\n    JOIN  MFCS_RDS.RDS_WV_SUBCLASS                  sc   ON  im.DEPT     = sc.DEPT\\n                                                        AND  im.CLASS    = sc.CLASS\\n                                                        AND  im.SUBCLASS = sc.SUBCLASS\\n    LEFT JOIN MFCS_RDS.RDS_WV_SUPS                  sp   ON  oh.SUPPLIER  = sp.SUPPLIER\\n    LEFT JOIN MFCS_RDS.RDS_WV_STORE                 st   ON  ol.LOCATION  = st.STORE\\n    LEFT JOIN MFCS_RDS.RDS_WV_WH                    wh   ON  ol.LOCATION  = wh.WH\\n    WHERE\\n        oh.STATUS IN ('W','S','A')\\n        AND oh.WRITTEN_DATE &gt;= ADD_MONTHS(SYSDATE, -3)\\n\\n)\\n\\nWHERE\\n    (\\n        WRONG_LEVEL_FLAG   = 'Y'\\n        OR NOT_ORDERABLE_FLAG = 'Y'\\n        OR WRONG_STATUS_FLAG  = 'Y'\\n        OR WRONG_NUMBER_TYPE  = 'Y'\\n    )\\n\"},\"editorCurrentState\":false,\"joins\":{\"tables\":[]}}</ds:uiOptions><ds:version>v5</ds:version></ds:datasetImportOptions>","business-model":"\"\"","active":true,"custom-attrs":"{\"src_parquet_verified\":\"true\"}","description":"External dataset","display-name":"Manual Query","locale":"sys","is-user-striped":false,"file-length":0,"type":"sql","properties-last-modified":"2026-07-30T03:18:54.914+0000","connection-namespace":"disadmin_disadmin_APPID","private-connection":false,"credential-exists":true,"connection-name":"Remote RDS MFCS Connection","provider-type":"db","provider-name":"oracle","sso-enabled":false,"datamodelname":"'ReCommon'.'RPT_103_Mfg_Plant_Orders_Wrong_Item_Type'","parent-namespace":"ReCommon","parent-name":"RPT_103_Mfg_Plant_Orders_Wrong_Item_Type","data-access-mode":"auto","is-data-cacheable":true,"checkpoint-metadata-stale":false,"owner-guid":"ReCommon","is-temporary":false},"datasetType":"EMBEDDED","datamodelTwoPartName":"'ReCommon'.'RPT_103_Mfg_Plant_Orders_Wrong_Item_Type'"}
